import itertools

def find_kth_smallest_sum_of_squares(k):
    sums = set()
    # We need to search until we have at least k unique sums.
    # A bound of y <= 25 should be sufficient for k=20, let's check.

    limit_y = 30 

    for y in range(2, limit_y + 1):
        for x in range(1, y):
            m = x**2 + y**2
            sums.add(m)

    sorted_sums = sorted(list(sums))

    if len(sorted_sums) < k:
        print(f"Warning: Only found {len(sorted_sums)} unique sums within the limit of y={limit_y}.")

    if k <= len(sorted_sums):
        return sorted_sums[k-1]
    else:
        return None

k = 20
result = find_kth_smallest_sum_of_squares(k)
print(f"The {k}th smallest good number is: {result}")
